INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(54211, 'Exodus 33:12', 'Exodus', 33, 12, 'موسی څښتن ته وویل: «ته ماته وایې چې دغه قوم بوځه، خو دا دې راته ونه ویل چې څوک راسره لېږې. تا ماته ویلي دي چې زه تا ښه پېژنم او ستا څخه خوشحاله یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_12.mp3', '', 1761754199, 1761754199),
(54212, 'Exodus 33:13', 'Exodus', 33, 13, 'که چېرې ته زما څخه خوشحاله یې، نو ماته دې خپل پلانونه ووایه، ترڅو تا وپېژنم او تل دې خوشحاله کړم. دا مه هېروه چې دا قوم ستا خپل قوم دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_13.mp3', '', 1761754199, 1761754199),
(54213, 'Exodus 33:14', 'Exodus', 33, 14, 'څښتن په ځواب کې وویل: «زه به په خپله ستا سره لاړ شم او بری به درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_14.mp3', '', 1761754199, 1761754199),
(54214, 'Exodus 33:15', 'Exodus', 33, 15, 'موسی هغه ته وویل: «که چېرې ته زمونږ سره نه ځې، نو مونږ مه مجبوروه چې له دې ځای څخه لاړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_15.mp3', '', 1761754199, 1761754199),
(54215, 'Exodus 33:16', 'Exodus', 33, 16, 'خو که چېرې ته زمونږ سره لاړ شې، نو هرڅوک به په دې پوه شي چې ته د خپل قوم او زما څخه خوشحاله یې. په دې ډول به د نړۍ د نورو ټولو قومونو څخه زمونږ فرق وشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_16.mp3', '', 1761754199, 1761754199),
(54216, 'Exodus 33:17', 'Exodus', 33, 17, 'څښتن موسی ته وویل: «کومه غوښتنه چې تا کړې ده زه به هماغسې وکړم، ځکه چې زه تا ډېر ښه پېژنم او ستا څخه خوشحاله یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_17.mp3', '', 1761754199, 1761754199),
(54217, 'Exodus 33:18', 'Exodus', 33, 18, 'بیا موسی وویل: «اوس دې خپل جلال ماته وښایه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_18.mp3', '', 1761754199, 1761754199),
(54218, 'Exodus 33:19', 'Exodus', 33, 19, 'څښتن په ځواب کې وویل: «زه به ستا په مخکې تېر شم او ته به زما شان او شوکت وګورې او خپل پاک نوم به درته ووایم. زه څښتن یم او په چا باندې چې وغواړم رحم وکړم، نو په هغوی باندې رحم کوم او په چا باندې چې وغواړم مهربانه شم نو په هغوی باندې مهرباني کوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_19.mp3', '', 1761754199, 1761754199),
(54219, 'Exodus 33:20', 'Exodus', 33, 20, 'هغه زیاته کړه: «خو تا نه پرېږدم چې زما مخ ووینې، ځکه هېڅوک نه شي کولای چې زما مخ وویني او ژوندی پاتې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_20.mp3', '', 1761754199, 1761754199),
(54220, 'Exodus 33:21', 'Exodus', 33, 21, 'بیا څښتن وویل: «دلته زما په خوا کې یو ځای شته، ته کولای شې چې په یو ګټ باندې ودرېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_21.mp3', '', 1761754199, 1761754199),
(54221, 'Exodus 33:22', 'Exodus', 33, 22, 'کله چې زما جلال تېریږي، زه به تا د ګټ په یو چاود کې واچوم او په خپل لاس به دې پټ کړم، ترڅو زه تېر شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_22.mp3', '', 1761754199, 1761754199),
(54222, 'Exodus 33:23', 'Exodus', 33, 23, 'بیا به زه خپل لاس لېرې کړم او ته به زما شا ووینې، خو مخ به مې ونه وینې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_23.mp3', '', 1761754199, 1761754199),
(54223, 'Leviticus 25:1', 'Leviticus', 25, 1, 'د سینا په غره باندې څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_1.mp3', '', 1761754199, 1761754199),
(54224, 'Leviticus 25:2', 'Leviticus', 25, 2, '«د اسراییلیانو سره خبرې وکړه او ورته ووایه: کله چې تاسو هغې خاورې ته چې زه یې درکوم ورننوځئ، باید څښتن ته د درناوي په خاطر هر اووم کال د ځمکې د کرلو څخه ډډه وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_2.mp3', '', 1761754199, 1761754199),
(54225, 'Leviticus 25:3', 'Leviticus', 25, 3, 'شپږ کاله خپل پټي وکرئ او شپږ کاله د خپلو انګورو د تاکونو څانګې اصلاح کړئ او حاصلات یې راټول کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_3.mp3', '', 1761754199, 1761754199),
(54226, 'Leviticus 25:4', 'Leviticus', 25, 4, 'خو په اووم کال دې ځمکه بیخي شاړه پاتې شي، دا به څښتن ته وقف شوی کال وي. په دې کال کې خپل پټي مه کرئ او د خپلو انګورو د تاکونو څانګې مه اصلاح کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_4.mp3', '', 1761754199, 1761754199),
(54227, 'Leviticus 25:5', 'Leviticus', 25, 5, 'هغه غلې دانې مه رېبئ چې بې له کرلو په خپله راشنې کیږي او د خپلو هغو تاکونو څخه انګور مه راټولوئ چې څانګې یې اصلاح شوې نه وي. دا یو کال دی چې ځمکه په کې بیخي شاړه پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_5.mp3', '', 1761754199, 1761754199),
(54228, 'Leviticus 25:8', 'Leviticus', 25, 8, 'اووه ځلې اووه کاله وشمېرئ، چې ټول نهه څلوېښت کاله کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_8.mp3', '', 1761754199, 1761754199),
(54229, 'Leviticus 25:9', 'Leviticus', 25, 9, 'بیا د اوومې میاشتې په لسمه ورځ چې د کفارې ورځ ده، په ټول وطن کې سرني ووهئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_9.mp3', '', 1761754199, 1761754199),
(54230, 'Leviticus 25:10', 'Leviticus', 25, 10, 'په دې ډول به تاسو پنځوسم کال سپېڅلی کال وګڼئ او د وطن ټولو اوسېدونکو ته به ازادي اعلان کړئ. د دې کال په دوران کې به هغه ټول جایداد چې خرڅ شوی وي، خپل اصلي خاوند یا د هغه اولادې ته بېرته ورکړل شي او هرڅوک چې د غلام په توګه خرڅ شوی وي، خپلې کورنۍ ته به ورستون شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_10.mp3', '', 1761754199, 1761754199),
(54231, 'Leviticus 25:11', 'Leviticus', 25, 11, 'پنځوسم کال به ستاسو دپاره د بېرته ورکولو کال وي. تاسو خپلې ځمکې ونه کرئ او هغه غلې دانې ونه رېبئ چې په خپله راشنې کیږي او د خپلو هغو تاکونو څخه انګور مه راټولوئ چې څانګې یې اصلاح شوې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_11.mp3', '', 1761754199, 1761754199),
(54232, 'Leviticus 25:12', 'Leviticus', 25, 12, 'د بېرته ورکولو ټول کال به ستاسو دپاره پاک وي، تاسو به یوازې هغه څه خورئ چې په پټي کې په خپل سر راشنه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_12.mp3', '', 1761754199, 1761754199),
(54233, 'Leviticus 25:13', 'Leviticus', 25, 13, 'په دې کال کې به هغه ټول جایداد چې خرڅ شوی وي، خپل اصلي خاوند ته بېرته ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_13.mp3', '', 1761754199, 1761754199),
(54234, 'Leviticus 25:14', 'Leviticus', 25, 14, 'که چېرې تاسو په خپل یو هېوادوال باندې ځمکه خرڅه کړئ یا یې ورڅخه واخلئ، د یو بل څخه ګټه مه اخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_14.mp3', '', 1761754199, 1761754199),
(54235, 'Leviticus 25:15', 'Leviticus', 25, 15, 'د ځمکې بیه دې د هغو کلونو د شمېر له مخې حساب شي چې د بېرته ورکولو د بل کاله پورې په کې دا ځمکه حاصل ورکولای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_15.mp3', '', 1761754199, 1761754199),
(54236, 'Leviticus 25:16', 'Leviticus', 25, 16, 'که چېرې کلونه ډېر وي، نو بیه به یې لوړه وي، خو که چېرې کلونه کم وي، نو بیه به یې ټیټه وي، ځکه چې څه چې خرڅیږي هغه به د فصلونو د شمېر له مخې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_16.mp3', '', 1761754199, 1761754199),
(54237, 'Leviticus 25:17', 'Leviticus', 25, 17, 'د یو بل څخه ګټه مه اخلئ خو زما څخه ووېرېږئ، ځکه چې زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_17.mp3', '', 1761754199, 1761754199),
(54238, 'Leviticus 25:18', 'Leviticus', 25, 18, 'د څښتن د ټولو فرمانونو او قوانینو څخه پیروي وکړئ، ترڅو په دې خاوره کې په امن سره ژوند وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_18.mp3', '', 1761754199, 1761754199),
(54239, 'Leviticus 25:19', 'Leviticus', 25, 19, 'ځمکه به خپل حاصلات ورکړي او تاسو چې هرڅه غواړئ د خوړلو دپاره به یې ولرئ او په امن کې به ژوند کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_19.mp3', '', 1761754199, 1761754199),
(54240, 'Leviticus 25:20', 'Leviticus', 25, 20, 'خو کېدای شي چې تاسو پوښتنه وکړئ: که چېرې مونږ څه شی ونه کرو او حاصل راټول نه کړو، نو په اووم کال به څه شی وخورو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_20.mp3', '', 1761754199, 1761754199),
(54241, 'Leviticus 25:21', 'Leviticus', 25, 21, 'زه به په شپږم کال تاسو ته داسې برکت درکړم چې ځمکه به د درېو کلونو دپاره پوره حاصل ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_21.mp3', '', 1761754199, 1761754199),
(54242, 'Leviticus 25:22', 'Leviticus', 25, 22, 'کله چې تاسو د اتم کال په دوران کې خپلې ځمکې وکرئ، د هغو حاصلاتو څخه به خواړه خورئ چې د شپږم کال په دوران کې راټول شوي وو او په نهم کال کې به هغه خواړه وخورئ چې تاسو په اتم کال کې کرلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_22.mp3', '', 1761754199, 1761754199),
(54243, 'Leviticus 25:23', 'Leviticus', 25, 23, 'تاسو باید خپله ځمکه د تل دپاره خرڅه نه کړئ، ځکه چې دا ستاسو نه ده. هغه ځمکه زما ده او تاسو په کې د هغو پردیو خلکو په شان یئ چې کولای شي د هغې څخه یوازې ګټه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_23.mp3', '', 1761754199, 1761754199),
(54244, 'Leviticus 25:24', 'Leviticus', 25, 24, 'کله چې ځمکه خرڅیږي، د هغې اصلي خاوند حق لري چې هغه بېرته په بیه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_24.mp3', '', 1761754199, 1761754199),
(54245, 'Leviticus 25:25', 'Leviticus', 25, 25, 'که چېرې ستاسو اسراییلیانو څخه یو کس غریب شي او مجبور شي چې د خپلې ځمکې څخه یو څه ځمکه خرڅه کړي، د هغه ډېر نژدې خپلوان باید هغه بېرته واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_25.mp3', '', 1761754199, 1761754199),
(54246, 'Leviticus 25:26', 'Leviticus', 25, 26, 'که چېرې یو کس یو خپلوان هم ونه لري چې هغه بېرته واخلي، کېدای شي چې هغه وروسته شتمن شي او پوره پیسې ولري چې هغه بېرته واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_26.mp3', '', 1761754199, 1761754199),
(54247, 'Leviticus 25:27', 'Leviticus', 25, 27, 'نو په داسې حالت کې هغه باید د حاصلاتو بیه د هغو کلونو دپاره معلومه کړي چې د بېرته ورکولو تر راتلونکي کاله پورې پاتې وي او د هغو پیسې دې هغه کس ته ورکړي چې ورباندې چې هغه خرڅه شوې وي. بیا هغه کولای شي چې بېرته خپله ځمکه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_27.mp3', '', 1761754199, 1761754199),
(54248, 'Leviticus 25:28', 'Leviticus', 25, 28, 'خو که چېرې اصلي خاوند نه شي کولای چې هغه ځمکه بېرته په بیه واخلي، نو هغه به د بېرته ورکولو د راتلونکي کال پورې د نوي خاوند وي. د بېرته ورکولو په کال به هغه بېرته خپل اصلي خاوند ته ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_28.mp3', '', 1761754199, 1761754199),
(54249, 'Leviticus 25:29', 'Leviticus', 25, 29, 'که چېرې یو کس په دېوال لرونکي ښار کې یو کور خرڅ کړي، دا حق لري چې د لومړي کال په ټول دوران کې د خرڅېدلو د نېټې څخه را په دې خوا هغه بېرته واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_29.mp3', '', 1761754199, 1761754199),
(54250, 'Leviticus 25:30', 'Leviticus', 25, 30, 'خو که چېرې هغه په دې کال کې بېرته وانخلي، د هغه د بېرته اخیستلو حق له لاسه ورکوي او هغه کور د اخیستونکي او د هغه د اولادې تلپاتې ملکیت کیږي. هغه به د بېرته ورکولو په کال کې بېرته ورنه کړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_30.mp3', '', 1761754199, 1761754199),
(54251, 'Leviticus 25:31', 'Leviticus', 25, 31, 'خو کوم کورونه چې په بې دېواله کلیو کې دي، په هغو باندې دې د پټیو په شان کار وشي. اصلي خاوند حق لري چې هغه بېرته واخلي او هغه دې د بېرته ورکولو په کال کې بېرته ورکړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_31.mp3', '', 1761754199, 1761754199),
(54252, 'Leviticus 25:32', 'Leviticus', 25, 32, 'لاویان دا حق لري چې خپل جایداد په هغو ښارونو کې چې هغوی ته ورکړل شوي دي، په هر وخت کې بېرته په بیه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_32.mp3', '', 1761754199, 1761754199),
(54253, 'Leviticus 25:33', 'Leviticus', 25, 33, 'که چېرې یو لاوي د دغو ښارونو څخه په یو ښار کې یو کور خرڅ کړي او بېرته یې وانخلي، هغه باید د بېرته ورکولو په کال کې بېرته ورکړای شي، ځکه چې د اسراییلو د قوم په منځ کې چې لاویان په خپلو ښارونو کې کوم کورونه لري، هغه د هغوی تلپاتې ملکیت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_33.mp3', '', 1761754199, 1761754199),
(54254, 'Leviticus 25:34', 'Leviticus', 25, 34, 'خو هغه څړځایونه چې د لاویانو د ښارونو په شاوخوا کې دي، هغه به هېڅکله خرڅ نه شي. دا د تل دپاره د هغوی ملکیت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_34.mp3', '', 1761754199, 1761754199),
(54255, 'Leviticus 25:35', 'Leviticus', 25, 35, 'که چېرې یو اسراییلی چې تاسو سره نژدې اوسیږي غریب شي او خپل ځان ونه شي ساتلی، تاسو باید د هغه سره داسې مرسته وکړئ لکه څنګه یې چې د یو پردي یا موقتي اوسېدونکي سره کوئ، ترڅو هغه وکولای شي چې ستاسو په خوا کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_35.mp3', '', 1761754199, 1761754199),
(54256, 'Leviticus 25:36', 'Leviticus', 25, 36, 'د یو اسراییلي څخه هېڅ سود مه اخلئ، خو د خپل خدای څخه ووېرېږئ، ترڅو ستاسو هېوادوال وکولای شي چې ستاسو په خوا کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_36.mp3', '', 1761754199, 1761754199),
(54257, 'Leviticus 25:37', 'Leviticus', 25, 37, 'په هغو پیسو باندې چې تاسو یې ورته په پور ورکوئ د هغوی څخه سود مه اخلئ او په هغو خوړو باندې چې تاسو یې ورباندې خرڅوئ، ګټه مه اخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_37.mp3', '', 1761754199, 1761754199),
(54258, 'Leviticus 25:38', 'Leviticus', 25, 38, 'زه ستاسو څښتن خدای یم چې تاسو مې د مصر څخه راوویستلئ، ترڅو د کنعان ځمکه درکړم او ستاسو خدای اوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_38.mp3', '', 1761754199, 1761754199),
(54259, 'Leviticus 25:39', 'Leviticus', 25, 39, 'که چېرې یو اسراییلی چې تاسو سره نژدې اوسیږي دومره غریب شي چې خپل ځان په تاسو باندې د غلام په توګه خرڅ کړي، تاسو به په هغه باندې د غلامانو کار نه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_39.mp3', '', 1761754199, 1761754199),
(54260, 'Leviticus 25:40', 'Leviticus', 25, 40, 'د هغه سره دې د مزدور یا هغه موقتي اوسېدونکي په شان چلند وشي چې ستاسو په منځ کې اوسیږي. هغه اسراییلی دې د بېرته ورکولو تر بل کاله پورې ستاسو خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_40.mp3', '', 1761754199, 1761754199),
(54261, 'Leviticus 25:41', 'Leviticus', 25, 41, 'په هغه وخت کې به هغه او د هغه اولادونه ستاسو څخه لاړ شي او خپلې کورنۍ او د خپلو نیکونو ملکیت ته به ورستانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_41.mp3', '', 1761754199, 1761754199),
(54262, 'Leviticus 25:42', 'Leviticus', 25, 42, 'اسراییلیان زما غلامان دي چې ما د مصر څخه راوویستل. په دې خاطر باید هغوی د غلامانو په توګه خرڅ نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_42.mp3', '', 1761754199, 1761754199),
(54263, 'Leviticus 25:43', 'Leviticus', 25, 43, 'د خپل خدای څخه ووېرېږئ او د هغوی سره سخت چلند مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_43.mp3', '', 1761754199, 1761754199),
(54264, 'Leviticus 25:44', 'Leviticus', 25, 44, 'که چېرې تاسو غلامانو ته اړتیا لرئ، کولای شئ چې د خپل شاوخوا قومونو څخه یې په بیه واخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_44.mp3', '', 1761754199, 1761754199),
(54265, 'Leviticus 25:45', 'Leviticus', 25, 45, 'همدارنګه تاسو کولای شئ چې ځینې پردي خلک چې ستاسو په منځ کې اوسیږي او د هغوی اولادونه چې ستاسو په خاوره کې پیدا شوي دي هم په بیه واخلئ. هغوی به ستاسو ملکیت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_45.mp3', '', 1761754199, 1761754199),
(54266, 'Leviticus 25:46', 'Leviticus', 25, 46, 'وروسته تاسو هغوی خپلو اولادونو ته د میراث په توګه پرېښودلی شئ او د ټول عمر دپاره ورڅخه غلامان جوړولی شئ. خو د خپلو اسراییلیانو سره باید سخت چلند ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_46.mp3', '', 1761754199, 1761754199),
(54267, 'Leviticus 25:47', 'Leviticus', 25, 47, 'فرض کړئ یو پردی یا یو داسې موقتي اوسېدونکی چې ستاسو په منځ کې اوسیږي شتمن شي، خو کوم اسراییلی غریب شي او خپل ځان په هغه پردی کس یا د هغه کس د کورنۍ په غړي باندې د غلام په توګه خرڅ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_47.mp3', '', 1761754199, 1761754199),
(54268, 'Leviticus 25:48', 'Leviticus', 25, 48, 'هغه د خرڅېدلو څخه وروسته بیاهم حق لري چې بېرته په بیه واخیستل شي. یو ورور،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_48.mp3', '', 1761754199, 1761754199),
(54269, 'Leviticus 25:49', 'Leviticus', 25, 49, 'یا یو تره یا یو د تره زوی یا یو بل نژدې خپلوان یې بېرته اخیستلی شي. که چېرې هغه په خپله پوره پیسې لاسته راوړي، خپله ازادي په خپله اخیستلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_49.mp3', '', 1761754199, 1761754199),
(54270, 'Leviticus 25:50', 'Leviticus', 25, 50, 'هغه باید د هغه چا سره چې دی یې اخیستی دی مشوره وکړي او د هغه وخت څخه چې خپل ځان یې خرڅ کړی ؤ د بېرته ورکولو د بل کاله پورې کلونه دې وشمېري او د هغه د ازادېدلو بیه دې د پاتې کلونو د هغه نرخ له مخې وي چې یو مزدور ته د هغو کلونو د شمېر په حساب ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_50.mp3', '', 1761754199, 1761754199),
(54271, 'Leviticus 25:53', 'Leviticus', 25, 53, 'د هغه سره دې د داسې مزدورانو په شان چلند وشي چې د کال په حساب اجیران نیول کیږي. تاسو باید وګورئ چې د هغه خاوند د هغه سره سخت چلند ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_53.mp3', '', 1761754199, 1761754199),
(54272, 'Leviticus 25:54', 'Leviticus', 25, 54, 'حتی که چېرې هغه په دغو طریقو ازاد نه شي، د بېرته ورکولو په راتلونکي کال باید هغه او د هغه اولادونه ازاد شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_54.mp3', '', 1761754199, 1761754199),
(54273, 'Leviticus 25:55', 'Leviticus', 25, 55, 'دا ځکه چې اسراییلیان زما غلامان دي چې ما د مصر څخه راوویستل. زه د هغوی څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus25_verse_55.mp3', '', 1761754199, 1761754199),
(54274, 'Numbers 11:1', 'Numbers', 11, 1, 'د اسراییلو قوم د خپلو تکلیفونو په هکله څښتن ته شکایت کول پیل کړل. کله چې څښتن د هغوی شکایت واورېد، هغه په قهر شو او په قوم باندې یې اور نازل کړ. د هغوی په منځ کې اور بلېده او د کمپ یوه څنډه یې له منځه یووړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_1.mp3', '', 1761754199, 1761754199),
(54275, 'Numbers 11:2', 'Numbers', 11, 2, 'کله چې قوم موسی ته د مرستې دپاره زاري وکړه، هغه څښتن ته دعا وکړه او اور مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_2.mp3', '', 1761754199, 1761754199),
(54276, 'Numbers 11:3', 'Numbers', 11, 3, 'نو هغه ځای د تبعیره په نوم یاد شو، ځکه چې هلته د هغوی په منځ کې د څښتن له خوا اور لګېدلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_3.mp3', '', 1761754199, 1761754199),
(54277, 'Numbers 11:4', 'Numbers', 11, 4, 'ځینې پردي خلک وو چې د اسراییلیانو سره راغلي وو. د هغوی غوښې ته ډېر سخت زړه کېده او حتی په خپله اسراییلیانو هم په شکایت کولو پیل وکړ او ویې ویل: «کاشکې مونږ ته د خوراک دپاره لږه غوښه وای!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_4.mp3', '', 1761754199, 1761754199),
(54278, 'Numbers 11:5', 'Numbers', 11, 5, 'څومره ماهیان چې مونږ غوښتل په مصر کې مو وړیا خوړلی شول او هلته بادرنګ، هندوانې، ګندنه، پیاز او هوږه هم وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_5.mp3', '', 1761754199, 1761754199),
(54279, 'Numbers 11:6', 'Numbers', 11, 6, 'خو دلته زمونږ اشتها له منځه لاړه، بې له دې من څخه مونږ بل هېڅ شی ونه لید.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_6.mp3', '', 1761754199, 1761754199),
(54280, 'Numbers 11:7', 'Numbers', 11, 7, 'من د دڼیا د تخم په شان ؤ، خو رنګ یې سپین بخن ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_7.mp3', '', 1761754199, 1761754199),
(54281, 'Numbers 11:10', 'Numbers', 11, 10, 'موسی د هرې کورنۍ د خلکو ژړا چې هر یو د خپلې خېمې د دروازې په خوله کې ولاړ ؤ او ژړل یې، واورېدله. څښتن ډېر زیات په قهر شو او په دې باندې موسی خفه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_10.mp3', '', 1761754199, 1761754199),
(54282, 'Numbers 11:11', 'Numbers', 11, 11, 'هغه څښتن ته وویل: «خپل خدمتګار دې ولې د داسې تکلیف سره مخامخ کړی دی؟ ما څه کړي دي چې زما څخه ناراضه شوی یې او د ټول قوم بار دې زما په اوږو باندې ایښی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_11.mp3', '', 1761754199, 1761754199),
(54283, 'Numbers 11:12', 'Numbers', 11, 12, 'هغوی ما نه دي پیدا کړي او نه مې هغوی زېږولي دي! ولې زما څخه غواړې چې د یوې دایي په شان کار وکړم او هغوی لکه د ماشومانو په شان په ټوله لار کې په غېږ کې واخلم او هغه وطن ته یې بوځم چې د هغوی د نیکونو سره دې وعده کړې وه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_12.mp3', '', 1761754199, 1761754199),
(54284, 'Numbers 11:13', 'Numbers', 11, 13, 'هغوی ماته ژاړي چې مونږ ته غوښه راکړه چې ویې خورو. د دې ټول قوم دپاره غوښه د کوم ځای څخه راپیدا کړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_13.mp3', '', 1761754199, 1761754199),
(54285, 'Numbers 11:14', 'Numbers', 11, 14, 'دا کار زما دپاره ډېر سخت دی. زه یوازې څنګه کولای شم چې د دغو ټولو خلکو مسوولیت په غاړه واخلم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_14.mp3', '', 1761754199, 1761754199),
(54286, 'Numbers 11:15', 'Numbers', 11, 15, 'که چېرې ته زما سره دا ډول چلند کوې، نو په ما باندې رحم وکړه او همدا اوس مې مړ کړه او دا بدبخته ژوند مې پای ته ورسوه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_15.mp3', '', 1761754199, 1761754199),
(54287, 'Numbers 11:16', 'Numbers', 11, 16, 'څښتن موسی ته وویل: «اویا تنه عزتمن خلک چې د قوم د مشرانو په توګه پېژندل شوي وي راټول کړه. هغوی ماته سپېڅلې خېمې ته راوله او ورته ووایه چې ستا په څنګ کې ودریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_16.mp3', '', 1761754199, 1761754199),
(54288, 'Numbers 11:17', 'Numbers', 11, 17, 'زه به درښکته شم او هلته به ستا سره خبرې وکړم او د هغه روح څخه به چې تاته مې درکړی دی لږ واخلم او هغوی ته به یې ورکړم. بیا هغوی کولای شي چې ستا سره د دغو خلکو دپاره د مسوولیت په درلودلو کې مرسته وکړي او ته به مجبور نه یې چې یوازې ته دا مسوولیت په غاړه واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_17.mp3', '', 1761754199, 1761754199),
(54289, 'Numbers 11:18', 'Numbers', 11, 18, 'اوس قوم ته ووایه: ‹د سبا دپاره خپل ځانونه پاک کړئ، تاسو به غوښه وخورئ. څښتن اورېدلي دي چې تاسو فریاد کوئ او وایئ چې کاشکې زمونږ سره لږه غوښه وای او مونږ په مصر کې ډېر ښه وو. اوس به څښتن تاسو ته غوښه درکړي او تاسو به یې وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_18.mp3', '', 1761754199, 1761754199),
(54290, 'Numbers 11:19', 'Numbers', 11, 19, 'تاسو به هغه یوازې یوه، دوه، پنځه، لس یا حتی شل ورځې نه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_19.mp3', '', 1761754199, 1761754199),
(54291, 'Numbers 11:20', 'Numbers', 11, 20, 'بلکې پوره یوه میاشت به یې وخورئ، ترڅو ستاسو د سپېږمو څخه راووځي او زړه مو ورڅخه تور شي. داسې به وشي، ځکه چې تاسو د څښتن څخه چې ستاسو په منځ کې حاضر دی منکر شوي یئ او دا شکایت مو کړی دی چې باید هېڅکله د مصر څخه وتلي نه وای.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_20.mp3', '', 1761754199, 1761754199),
(54292, 'Numbers 11:21', 'Numbers', 11, 21, 'موسی په ځواب کې وویل: «دلته زما سره لږ تر لږه شپږ لکه کسان دي. نو څنګه ویلی شې چې د هغوی دپاره به دا غوښه پوره یوه میاشت کفایت وکړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_21.mp3', '', 1761754199, 1761754199),
(54293, 'Numbers 11:22', 'Numbers', 11, 22, 'حتی که چېرې ټولې رمې او پادې هم حلالې شي یا د بحیرې ټول ماهیان هم ونیول شي، د هغوی دپاره به کفایت ونه کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_22.mp3', '', 1761754199, 1761754199),
(54294, 'Numbers 11:23', 'Numbers', 11, 23, 'څښتن په ځواب کې وویل: «زه هرڅه کولای شم! ته به زر ووینې چې زما خبرې به رښتیا شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_23.mp3', '', 1761754199, 1761754199),
(54295, 'Numbers 11:24', 'Numbers', 11, 24, 'نو موسی د سپېڅلې خېمې څخه راووت او څه چې څښتن ویلي وو هغه یې قوم ته بیان کړل. هغه اویا تنه مشران راټول کړل او د خېمې شاوخوا یې ودرول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_24.mp3', '', 1761754199, 1761754199),
(54296, 'Numbers 11:25', 'Numbers', 11, 25, 'بیا څښتن په ورېځ کې راښکته شو او د موسی سره یې خبرې وکړې. څښتن د هغه روح څخه چې موسی ته یې ورکړی ؤ، لږ واخیست او اویا مشرانو ته یې ورکړ. کله چې د څښتن روح په هغوی باندې نازل شو، نو هغوی د نبیانو په شان په نبوت پیل وکړ، خو دا کار یې یوازې د یوځل دپاره وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_25.mp3', '', 1761754199, 1761754199),
(54297, 'Numbers 11:26', 'Numbers', 11, 26, 'الداد او میداد دوه مشران وو چې په کمپ کې پاتې وو او خېمې ته تللي نه وو. خو کله چې په هغوی باندې هم روح نازل شو، نو په کمپ کې یې نبوت پیل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_26.mp3', '', 1761754199, 1761754199),
(54298, 'Numbers 11:27', 'Numbers', 11, 27, 'یو ځوان موسی ته ورمنډه کړه او د الداد او میداد په هکله یې ورته خبر ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_27.mp3', '', 1761754199, 1761754199),
(54299, 'Numbers 11:28', 'Numbers', 11, 28, 'د نون زوی یوشع چې د خپلې ځوانۍ د وخت څخه د موسی مرستیال ؤ، وویل: «ای موسی زما باداره، هغوی منع کړه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_28.mp3', '', 1761754199, 1761754199),
(54300, 'Numbers 11:29', 'Numbers', 11, 29, 'خو موسی په ځواب کې وویل: «ایا ستا سره دا اندېښنه ده چې هغوی به په ما باندې څه وکړي؟ کاشکې څښتن خپل روح په خپل ټول قوم باندې نازل کړي، نو هرڅوک به نبي شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_29.mp3', '', 1761754199, 1761754199),
(54301, 'Numbers 11:30', 'Numbers', 11, 30, 'بیا موسی او د اسراییلو اویا مشران بېرته کمپ ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_30.mp3', '', 1761754199, 1761754199),
(54302, 'Numbers 11:31', 'Numbers', 11, 31, 'له هغې وروسته څښتن یو قوي باد رانازل کړ چې مړزان یې د بحیرې څخه راوړل. هغه د ځمکې څخه د یو متر څخه په کمه فاصله کې پورته الوتل، ترڅو د اسراییلیانو په کمپ او د هغه په شاوخوا باندې د څو څو کیلومترو په فاصله له هرې خوا څخه راښکته شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_31.mp3', '', 1761754199, 1761754199),
(54303, 'Numbers 11:32', 'Numbers', 11, 32, 'نو خلکو ټوله ورځ او ټوله شپه او ټوله راتلونکې ورځ مړزان ونیول. هېچا د زرو کیلو ګرامو څخه کم نه وو راټول کړي. هغه یې د وچېدلو دپاره د کمپ شاوخوا ته وغوړول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_32.mp3', '', 1761754199, 1761754199),
(54304, 'Numbers 11:33', 'Numbers', 11, 33, 'خو د غوښې د خوراک د شروع سره سم څښتن په قوم باندې په قهر شو او په کمپ باندې یې سخته وبا نازله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_33.mp3', '', 1761754199, 1761754199),
(54305, 'Numbers 11:34', 'Numbers', 11, 34, 'هغه ځای د قبروت هتاوه (د حریصانو د قبرونو) په نوم یاد شو، ځکه چې په هغه ځای کې هغه خلک ښخ شول چې غوښې ته به یې سخت زړه کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_34.mp3', '', 1761754199, 1761754199),
(54306, 'Numbers 11:35', 'Numbers', 11, 35, 'د هغه ځای څخه قوم حضیروت ته سفر وکړ او هلته یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers11_verse_35.mp3', '', 1761754199, 1761754199),
(54307, 'Psalms 145:1', 'Psalms', 145, 1, 'بیانوم به ستا لویي ای زما خدایه ای زما پاچا زه تر ابده به کوم ستا د نامه ستاینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_1.mp3', '', 1761754199, 1761754199),
(54308, 'Psalms 145:2', 'Psalms', 145, 2, 'زه هره ورځ به ستا ثنا وایمه ثنا او صفت به ستا د نوم کړم تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_2.mp3', '', 1761754199, 1761754199),
(54309, 'Psalms 145:3', 'Psalms', 145, 3, 'څښتن لوی دی او لایق دی د ډېر زیات صفت زمونږ د پوهې نه بهر ده د هغه لویي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_3.mp3', '', 1761754199, 1761754199),
(54310, 'Psalms 145:4', 'Psalms', 145, 4, 'ستا د کارونو به صفت کیږي له یوه نسل نه تر بله پورې بیانوي به هغوی ستا زورور کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_4.mp3', '', 1761754199, 1761754199);